from flask import Flask, request
app = Flask(__name__)

@app.route('/')
def root():
    return '''
    <h1>Welcome to my3🔐</h1>
    <p>I'm your personal secretary</p>
    '''

@app.route('/<page>')
def page(page):
    if page == 'page1':
        return '''
        <h1>Hello World</h1>
        <p>I'm your personal secretary</p>
        '''

    elif page == 'page2':
        name = request.args.get('name')
        return '''
        <h1>Hello {}</h1>
        <p>I'm your personal secretary</p>
        '''.format(name)

    else:
        return '404 Not Found'
